namespace {using namespace gf;unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"Story widgets: %s\n",why);std::abort();}}
std::vector<u8> read(const char* path){std::ifstream file(path,std::ios::binary);check(bool(file),"input file");return {std::istreambuf_iterator<char>(file),{}};}
void owned(){const auto lib=force_inventory_fixture::catalog();ForceInventory owner;check(owner.create(lib)&&owner.place(19,0,1)==ForceChange::Applied,"nonempty rows");const auto art=story_force_widgets_fixture::art();StoryForceWidgets visual;check(visual.open(art,owner,19),"constructor callbacks");check(visual.background_time()==1&&visual.title_counter()==1&&visual.footer_counter()==0&&visual.arrow_counter()==31&&!visual.arrow_mask(),"constructor/update clocks distinct");
    check(visual.step(owner,19,4,0)&&visual.arrow_counter()==32&&visual.arrow_mask()==32&&visual.draws().back().type==6,"active arrows first visible");check(visual.step(owner,19,0,4)&&visual.arrow_counter()==33&&visual.arrow_mask()==2&&visual.draws().back().type!=6,"closing arrow bit changes");check(visual.step(owner,19,0,4)&&visual.draws().back().type==6,"closing blink2");
    check(visual.open(art,owner,0),"clock cohort");for(unsigned frame=1;frame<=256;++frame){check(visual.step(owner,frame&1?19:0,4,0),"owned callback");const auto n=frame+1;const unsigned title=n<128?n:64+(n-128)%64;check(visual.title_counter()==title&&visual.footer_counter()==u16(frame)&&visual.background_time()==f32(n%120),"source wrap120/title128subtract64/footer16bit");for(const auto& draw:visual.draws())if(draw.type==4&&!draw.text&&draw.part>=2)check(draw.material_time>=0&&draw.material_time<=9,"force number selectors");}
    const auto rev=owner.revision();check(visual.current(owner)&&owner.revision()==rev,"no inventory mutation");check(owner.rename_force(19,"UPDATED")==ForceChange::Applied&&!visual.step(owner,19,4,0)&&!visual.ready()&&visual.draws().empty(),"stale failure clears publications");
    check(visual.open(art,owner,19)&&owner.rename_force(19,"RETURNED")==ForceChange::Applied&&visual.rebind_inventory(owner)&&visual.draws().empty()&&visual.step(owner,19,4,0)&&visual.name()=="RETURNED","explicit graphics revision adoption");check(owner.create(lib)&&!visual.rebind_inventory(owner),"reloaded owner refuses");
    check(visual.open(art,owner,0,4,0)&&!visual.arrow_mask()&&visual.arrow_counter()==31,"one stored row has no arrows");check(!visual.step(owner,0,1,0),"unrepresented bit mask");
    auto b=story_force_widgets_fixture::bytes();StoryForceWidgetsArt loaded;std::string error;const auto cards=story_force_cards_fixture::art();for(unsigned size=0;size<280;++size)check(!loaded.load({b.data(),size},cards,&error)&&!loaded.ready(),"profile truncation");b[11]^=1;check(!loaded.load({b.data(),b.size()},cards,&error),"bank binding");
    std::printf("Story force widgets: %u owned checks PASS; source callback clocks only\n",checks);
}
void source(int argc,char** argv){check(argc==11,"source args");const auto wb=read(argv[1]),cb=read(argv[2]),pb=read(argv[3]),sb=read(argv[4]),ib=read(argv[5]),catalog_bytes=read(argv[6]),map_bytes=read(argv[7]),fp=read(argv[8]),ft=read(argv[9]);std::string error;StoryForceCardArt card;check(card.load({cb.data(),cb.size()},{pb.data(),pb.size()},&error),error.c_str());StoryForceWidgetsArt art;check(art.load({wb.data(),wb.size()},card,&error),error.c_str());HsdRecordAnimationBank setup,icons;check(setup.load({sb.data(),sb.size()},&error,true)&&icons.load({ib.data(),ib.size()},&error,true),error.c_str());ForceCatalog catalog;check(catalog.load({catalog_bytes.data(),catalog_bytes.size()},&error),error.c_str());ForceEditorArt mapping;check(mapping.load({map_bytes.data(),map_bytes.size()},catalog,&error),error.c_str());SourceFont font;check(font.load({fp.data(),fp.size()},{ft.data(),ft.size()},&error),error.c_str());
    ForceInventory owner;check(owner.create(catalog)&&owner.place(19,0,1)==ForceChange::Applied&&owner.place(19,1,2)==ForceChange::Applied&&owner.place(7,0,2)==ForceChange::Applied,"declared source inventory");for(unsigned force:{0u,7u,19u})check(owner.rename_force(force,"STORY"+std::to_string(force))==ForceChange::Applied,"names");const auto revision=owner.revision();StoryForceWidgets visual;check(visual.open(art,owner,0),"source visual construction");RecordingRenderBackend backend;RenderEngine render(backend);check(render.initialize({640,480,false,true,"Story page CPU"},nullptr,&error),"recording renderer");StoryForcePageScene scene;check(scene.load_prepared(art,card,setup,icons,mapping,font,render,&error),error.c_str());
    FILE* file=std::fopen(argv[10],"wx");check(file,"exclusive test wire");auto word=[&](u32 v){u8 b[4];store_be32(b,v);check(std::fwrite(b,1,4,file)==4,"wire");};
    for(unsigned frame=0;frame<256;++frame){const unsigned force=frame<80?0:frame<160?19:7;const u8 interactive=frame>=4&&frame<180?4:0,closing=frame>=180&&frame<224?4:0;if(frame)check(visual.step(owner,force,interactive,closing),"source widget callback");StoryForceCardPlan plan;check(story_force_card_plan(card,owner,force,500,&plan),"coherent source cards");
        for(u32 v:{frame,force,f32_to_bits(visual.background_time()),u32(visual.title_counter()),u32(visual.footer_counter()),u32(visual.arrow_counter()),u32(visual.arrow_mask()),u32(visual.draws().size())})word(v);
        word(u32(visual.name().size()));std::array<u8,41> name{};std::copy(visual.name().begin(),visual.name().end(),name.begin());check(std::fwrite(name.data(),1,name.size(),file)==name.size(),"name wire");
        for(unsigned index=0;index<32;++index){if(index<visual.draws().size()){const auto& d=visual.draws()[index];for(u32 v:{u32(d.record),u32(d.type),u32(d.part),u32(d.mask),u32(d.authored_world),u32(d.text),f32_to_bits(d.joint_time),f32_to_bits(d.material_time)})word(v);for(f32 f:d.world.m)word(f32_to_bits(f));}else for(unsigned i=0;i<24;++i)word(0);}
        render.begin_frame({0,0,0,0});render.reset_arena();render.state()={};const bool ok=scene.draw(render,visual,plan,owner,&error);if(!ok)std::fprintf(stderr,"frame %u: %s\n",frame,error.c_str());check(ok,"whole page source widgets submission");check(render.end_frame(),"page end");render.present();check(backend.draws()>0&&backend.last_frame_digest()!=0&&owner.revision()==revision,"nonempty post-present/no mutation");std::printf("D %u %u %zu %u %llu\n",frame,force,visual.draws().size(),backend.draws(),static_cast<unsigned long long>(backend.last_frame_digest()));
    }
    check(std::fclose(file)==0,"wire close");render.shutdown();std::puts("Story source whole-page CPU256frames PASS; no GPU/fade/storage/mission authority");
}
}
int main(int argc,char** argv){owned();if(argc!=1)source(argc,argv);}
